<script lang="ts">
 import {onMount} from 'svelte';import {api,contentSaved} from '../lib/api.ts';import {messageOf} from '../lib/content.ts';import Icon from '../components/Icon.svelte';
 interface Status{head:string;branch:string;clean:boolean;pendingPushCount:number;pendingCommits:{sha:string;message:string;time:string}[];remoteAhead:boolean;healthy:boolean;lockedReason:string|null;}
 let status:Status|null=null,error='',message='',busy=false,loading=true;
 async function load(){loading=true;error='';try{status=await api.get<Status>('/git/status');}catch(e){error=messageOf(e);}finally{loading=false;}}
 async function publish(){if(busy)return;busy=true;message='';error='';try{const r=await api.post<{pushedCount:number}>('/publish',{});message=`已成功推送 ${r.pushedCount} 个提交。博客构建由托管平台自动触发，构建完成后内容才会在前台可见。`;contentSaved();await load();}catch(e){error=messageOf(e);}finally{busy=false;}}
 onMount(()=>{void load();});
</script>
<div class="page-heading"><div><div class="eyebrow">SITE / PUBLISH</div><h1>发布中心</h1><p class="muted">查看仓库状态，把准备好的内容分享出去。</p></div><button disabled={loading||busy} on:click={load}>刷新状态</button></div>
{#if error}<div class="err" role="alert">{error}</div>{/if}{#if message}<div class="msg" role="status">{message}</div>{/if}
{#if status}<div class="publish-banner"><span class="publish-icon"><Icon name="publish" size={28}/></span><div><h2>{status.pendingPushCount?`${status.pendingPushCount} 个提交，等待发布`:'当前没有待发布的提交'}</h2><p>保存内容后会生成提交；推送到远端仓库，触发博客自动构建。</p></div><button class="primary" disabled={busy||!status.pendingPushCount||!status.healthy||!status.clean} on:click={publish}>{busy?'正在推送…':'推送并触发构建'}<Icon name="arrow" size={15}/></button></div>
<div class="stats-grid"><div class="stat-card"><div class="stat-top">当前分支</div><strong class="branch">{status.branch}</strong><small>博客内容仓库</small></div><div class="stat-card"><div class="stat-top">工作区状态</div><strong class="branch">{status.clean?'干净':'存在未提交修改'}</strong><small>{status.clean?'所有修改已提交':'请先保存内容，或检查图片变更'}</small></div><div class="stat-card"><div class="stat-top">待推送提交</div><strong>{status.pendingPushCount}</strong><small>保留本地提交，推送失败可重试</small></div><div class="stat-card"><div class="stat-top">远端状态</div><strong class="branch">{status.remoteAhead?'需要同步':'无已知领先提交'}</strong><small>推送时会获取最新远端状态</small></div></div>
{#if !status.healthy||status.lockedReason}<div class="err">{status.lockedReason||'仓库状态异常，请先修复后再发布。'}</div>{/if}
<section class="panel"><div class="panel-head"><h2>待发布记录</h2><span class="badge neutral">{status.pendingPushCount} COMMITS</span></div>{#if !status.pendingCommits.length}<div class="empty"><Icon name="check" size={28}/><h3 style="margin-top:14px">内容已与仓库同步</h3><p class="muted">继续创作，下一次更新从这里出发。</p><a href="#/posts">回到文章管理 →</a></div>{:else}<div class="table-wrap"><table><thead><tr><th>提交说明</th><th>提交编号</th><th>保存时间</th></tr></thead><tbody>{#each status.pendingCommits as commit}<tr><td>{commit.message}</td><td><code>{commit.sha.slice(0,8)}</code></td><td>{new Date(commit.time).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}</td></tr>{/each}</tbody></table></div>{/if}</section>
<p class="hint" style="margin-top:22px">此处确认的是仓库推送结果。博客构建与上线状态请在托管平台查看，或<a href="https://www.cyberpioneer.club/" target="_blank" rel="noreferrer">访问博客验证 ↗</a>。</p>
{:else if loading}<div class="empty">正在检查仓库状态…</div>{/if}
<style>.publish-banner{display:flex;align-items:center;gap:20px;padding:28px;margin-bottom:25px;background:#eef1ff;border:1px solid #e0e5fb;border-radius:12px}.publish-icon{color:#7b89d0;background:#fff8;padding:16px;border-radius:12px}.publish-banner h2{font-size:18px;color:#53618b;margin-bottom:10px}.publish-banner p{font-size:12px;color:#8794b6;margin:0;line-height:1.8}.publish-banner button{margin-left:auto;white-space:nowrap}.stat-card strong.branch{font-size:17px;margin:22px 0 18px;overflow-wrap:anywhere}@media(max-width:900px){.publish-banner{flex-wrap:wrap;padding:20px}.publish-banner button{margin-left:0}}</style>
